./novamind-operation python-c "
import novamind_api as nm
# How many legacy \$12 subs remain?
r = nm.query(\"SELECT ROUND(s.effective_price,0) p, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' AND c.group_id='S1' GROUP BY p ORDER BY p\")
print('S1 price distribution:')
for row in r['rows']: print('price', row['p'], 'n', row['n'])
r = nm.query(\"SELECT ROUND(s.effective_price,0) p, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' AND c.group_id IN ('S2','S3') GROUP BY p ORDER BY p\")
print('S2/S3 price distribution:')
for row in r['rows']: print('price', row['p'], 'n', row['n'])
# usage last 7 days
r = nm.query(\"SELECT day, SUM(usage_units) u FROM usage_daily WHERE day>=56 GROUP BY day ORDER BY day\")
try:
    for row in r['rows']: print('usage', row['day'], row['u'])
except Exception as e:
    print('usage tbl err', e)
"

