./novamind-operation python-c "
import novamind_api as nm
r = nm.query(\"SELECT created_day as d, COUNT(*) as leads FROM customers WHERE created_day>70 GROUP BY created_day ORDER BY created_day\")
leads = {row['d']: row['leads'] for row in r['rows']}
r = nm.query(\"SELECT start_day as d, COUNT(*) as subs FROM subscriptions WHERE start_day>70 AND status='subscribed' GROUP BY start_day ORDER BY start_day\")
subs = {row['d']: row['subs'] for row in r['rows']}
r = nm.query(\"SELECT created_day as d, COUNT(*) as lost FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE c.created_day>70 AND s.status='lost' GROUP BY created_day ORDER BY created_day\")
lost = {row['d']: row['lost'] for row in r['rows']}
print('day leads subs lost conv%')
for d in sorted(leads):
    l = leads[d]; s = subs.get(d,0); lo = lost.get(d,0)
    print(d, l, s, lo, round(100*s/l,1) if l else '-')
"

